#!/usr/bin/python3

import pyrob.core as rob
import random
from pyrob.tasks import check_filled_cells, find_cells_to_be_filled

# Порядок вариантов: один раз перемешиваем при загрузке модуля — без повторений в пределах 0..1
_variant_order = list(range(2))
random.shuffle(_variant_order)

class Task:
    CHECKS = 2

    def load_level(self, n):
        idx = _variant_order[n % len(_variant_order)]
        if idx == 0:
            rob.set_field_size(7, 7)
            rob.set_cell_type(3, 4, rob.CELL_TO_BE_FILLED)
            rob.goto(3, 3)
            rob.put_wall(right=True, bottom=True)
            rob.goto(4, 2)
            rob.put_wall(right=True)
            rob.goto(5, 2)
            rob.put_wall(right=True)
            rob.goto(6, 2)
            rob.put_wall(right=True)
            rob.set_parking_cell(3, 4)
            rob.goto(3, 2)
        elif idx == 1:
            rob.set_field_size(7, 7)
            rob.set_cell_type(3, 4, rob.CELL_TO_BE_FILLED)
            rob.goto(0, 2)
            rob.put_wall(right=True)
            rob.goto(1, 2)
            rob.put_wall(right=True)
            rob.goto(2, 2)
            rob.put_wall(right=True)
            rob.goto(2, 3)
            rob.put_wall(bottom=True)
            rob.goto(3, 3)
            rob.put_wall(right=True)
            rob.set_parking_cell(3, 4)
            rob.goto(3, 2)

        self.cells_to_fill = find_cells_to_be_filled()

    def check_solution(self):
        return check_filled_cells(self.cells_to_fill) and rob.is_parking_point()
